<?php
/**
 * 短代码功能
 *
 * @package 好物页面插件
 */

if (!defined('WPINC')) {
    die;
}

/**
 * 注册短代码
 */
function goods_exhibition_register_shortcode()
{
    add_shortcode('goods_exhibition', 'goods_exhibition_shortcode_callback');
}
add_action('init', 'goods_exhibition_register_shortcode');

/**
 * 渲染单个商品卡片（复用模板）
 *
 * @param array $product 产品数据
 * @param bool $is_new 是否为新品
 * @return string HTML
 */
function goods_exhibition_render_product_card($product, $is_new = false)
{
    $item_url = !empty($product['url']) ? esc_url($product['url']) : '';
    $name = esc_html($product['name']);
    $desc = wp_kses_post($product['description']);
    $desc_plain = esc_attr(wp_strip_all_tags($product['description']));
    $suffix = !empty($product['price_suffix']) ? $product['price_suffix'] : '';
    $price = esc_html(goods_exhibition_format_price_display($product['price'], $suffix));
    $image_url = esc_url($product['image_url']);
    $badge_tag = !empty($product['badge_tag']) ? esc_html($product['badge_tag']) : '';
    $builtin_brand = !empty($product['brand']) ? esc_html($product['brand']) : '';
    $custom_brand = !empty($product['custom_brand']) ? esc_html($product['custom_brand']) : '';
    $brand = !empty($custom_brand) ? $custom_brand : $builtin_brand;

    // 存储完整商品数据供详情弹窗提取
    $product_json = esc_attr(wp_json_encode(array(
        'name' => $product['name'],
        'description' => $product['description'],
        'price' => goods_exhibition_format_price_display($product['price'], $suffix),
        'image_url' => $image_url,
        'url' => !empty($product['url']) ? $product['url'] : '',
        'category' => !empty($product['category']) ? $product['category'] : '',
        'is_new' => $is_new ? 1 : 0,
        'badge_tag' => $badge_tag,
        'brand' => $brand,
        'cta_text' => '详情',
    )));

    // 构建卡片内部内容
    $inner = '<div class="goods-exhibition-content">';

    // 标题行：左侧品名，右侧 NEW 标签
    $inner .= '<div class="goods-card-header-row">';
    $inner .= '<h3 class="goods-exhibition-title" title="' . esc_attr($product['name']) . '">' . $name . '</h3>';
    if ($is_new) {
        $inner .= '<span class="goods-exhibition-new-badge">NEW</span>';
    }
    $inner .= '</div>';

    // 核心卖点与规格副标
    $inner .= '<div class="goods-exhibition-description" title="' . $desc_plain . '">' . $desc . '</div>';

    // 价格与操作按钮同行显示（如 ¥9499起 与 详情）
    $inner .= '<div class="goods-exhibition-price-row">';
    if (!empty($price)) {
        $inner .= '<div class="goods-exhibition-price">' . $price . '</div>';
    } else {
        $inner .= '<div class="goods-exhibition-price-placeholder"></div>';
    }
    $inner .= '<button type="button" class="goods-exhibition-quickview-btn" aria-label="查看商品详情" title="查看完整详情" data-img="' . $image_url . '" data-product="' . $product_json . '">详情</button>';
    $inner .= '</div>';
    $inner .= '</div>';

    // 图片容器：正方形等比，底角浮动特色胶囊（支持最多2个同时显示）
    $inner .= '<div class="goods-exhibition-image-container goods-exhibition-image-trigger no-lightbox no-zoom viewer-ignore ignore-lightbox" role="button" tabindex="0" aria-label="' . esc_attr($product['name']) . ' 详情" data-no-viewer="true" data-no-lightbox="true" data-lightbox="false" data-fancybox="none" data-no-zoom="true">';
    $inner .= '<img src="' . $image_url . '" alt="' . esc_attr($product['name']) . '"'
        . ' width="500" height="500" loading="lazy" class="goods-exhibition-image no-lightbox no-zoom viewer-ignore ignore-lightbox"'
        . ' data-no-viewer="true" data-no-lightbox="true" data-lightbox="false" data-fancybox="none" data-no-zoom="true" draggable="false">';

    // 卖点胶囊标签（解析逗号/分号/竖线分隔，最多展示前2个；严格不能按空格切分，确保完整保留「新品首发 🚀」等图文标签为单个整体）
    $badge_tags = array();
    if (!empty($badge_tag)) {
        $raw_tags = preg_split('/[,，、;；|]+/u', $badge_tag);
        foreach ($raw_tags as $t) {
            $t = trim($t);
            if ($t !== '') {
                $badge_tags[] = $t;
            }
            if (count($badge_tags) >= 2) {
                break;
            }
        }
    }

    if (!empty($badge_tags)) {
        $inner .= '<div class="goods-card-badge-container">';
        foreach ($badge_tags as $bt_item) {
            $inner .= '<span class="goods-card-badge-pill goods-tag-pill">' . esc_html($bt_item) . '</span>';
        }
        $inner .= '</div>';
    }
    $inner .= '</div>';

    // 卡片外层容器
    $item_classes = 'goods-exhibition-item is-clickable' . ($is_new ? ' is-new' : '');
    return '<div class="' . $item_classes . '" data-id="' . intval($product['id']) . '" data-brand="' . esc_attr($brand) . '" data-name="' . esc_attr($product['name']) . '" data-cat="' . esc_attr(!empty($product['category']) ? $product['category'] : '') . '" data-img="' . $image_url . '" data-product="' . $product_json . '" role="button" tabindex="0" aria-label="' . esc_attr($product['name']) . ' 详情">' . $inner . '</div>';
}

/**
 * 获取品牌 Logo HTML（内置主流科技品牌官方高清矢量SVG + 用户自定义Logo图片 + 质感文字兜底）
 *
 * @param string $brand_name 品牌名称或商品品名
 * @param string $custom_logo_url 自定义 Logo 图片 URL（可选）
 * @return string HTML
 */
function goods_exhibition_get_brand_logo($brand_name, $custom_logo_url = '')
{
    $brand_name = trim($brand_name);
    $custom_logo_url = trim($custom_logo_url);

    // 1. 若配置了自定义 Logo 图片，最高优先级渲染
    if (!empty($custom_logo_url)) {
        return '<div class="goods-poster-brand-logo is-custom-img" title="' . esc_attr($brand_name) . '">'
            . '<img src="' . esc_url($custom_logo_url) . '" alt="' . esc_attr($brand_name) . '" class="goods-brand-logo-img">'
            . '</div>';
    }

    if (empty($brand_name)) {
        return '';
    }

    // 统一转小写以支持大小写模糊匹配（如 Huawei、huawei、HUAWEI 等无缝命中），多字节 UTF-8 安全
    $lower = function_exists('mb_strtolower') ? mb_strtolower($brand_name, 'UTF-8') : strtolower($brand_name);

    // 2. 内置主流科技数码品牌官方高清矢量 SVG (0网络请求，矢量不失真)
