        return '<div class="goods-poster-brand-logo is-builtin-svg brand-xiaomi" title="Xiaomi 小米">'
            . '<svg viewBox="0 0 40 40" width="34" height="34" fill="none"><rect width="40" height="40" rx="9" fill="#FF6900"/><svg x="6" y="6" width="28" height="28" viewBox="0 0 24 24" fill="white"><path d="M4.906 7.405h5.624c1.47 0 3.007.068 3.764.827.746.746.827 2.233.83 3.676v4.54a.15.15 0 0 1-.152.147h-1.947a.15.15 0 0 1-.152-.148V11.83c-.002-.806-.048-1.634-.464-2.051-.358-.36-1.026-.441-1.72-.458H7.158a.15.15 0 0 0-.151.147v6.98a.15.15 0 0 1-.152.148H4.906a.15.15 0 0 1-.15-.148V7.554a.15.15 0 0 1 .15-.149zm12.131 0h1.949a.15.15 0 0 1 .15.15v8.892a.15.15 0 0 1-.15.148h-1.949a.15.15 0 0 1-.151-.148V7.554a.15.15 0 0 1 .151-.149zM8.92 10.948h2.046c.083 0 .15.066.15.147v5.352a.15.15 0 0 1-.15.148H8.92a.15.15 0 0 1-.152-.148v-5.352a.15.15 0 0 1 .152-.147Z"/></svg></svg>'
            . '</div>';
    }

    if (strpos($lower, 'apple') !== false || strpos($brand_name, '苹果') !== false || strpos($lower, 'iphone') !== false || strpos($lower, 'ipad') !== false || strpos($lower, 'macbook') !== false || strpos($lower, 'mac') !== false) {
        return '<div class="goods-poster-brand-logo is-builtin-svg brand-apple" title="Apple 苹果">'
            . '<svg viewBox="0 0 40 40" width="34" height="34" fill="none"><rect width="40" height="40" rx="9" fill="#000000"/><svg x="8" y="7" width="24" height="25" viewBox="0 0 24 24" fill="white"><path d="M12.152 6.896c-.948 0-2.415-1.078-3.96-1.04-2.04.027-3.91 1.183-4.961 3.014-2.117 3.675-.546 9.103 1.519 12.09 1.013 1.454 2.208 3.09 3.792 3.039 1.52-.065 2.09-.987 3.935-.987 1.831 0 2.35.987 3.96.948 1.637-.026 2.676-1.48 3.676-2.948 1.156-1.688 1.636-3.325 1.662-3.415-.039-.013-3.182-1.221-3.22-4.857-.026-3.04 2.48-4.494 2.597-4.559-1.429-2.09-3.623-2.324-4.39-2.376-2-.156-3.675 1.09-4.61 1.09zM15.53 3.83c.843-1.012 1.4-2.427 1.245-3.83-1.207.052-2.662.805-3.532 1.818-.78.896-1.454 2.338-1.273 3.714 1.338.104 2.715-.688 3.559-1.701"/></svg></svg>'
            . '</div>';
